const ciudades = [
  'Barranquilla', 'Bogotá', 'Medellín', 'Cali', 'Bucaramanga',
  'Cartagena', 'Pereira', 'Santa Marta', 'Ibagué', 'Manizales',
  'Cúcuta', 'Villavicencio', 'Montería', 'Valledupar', 'Pasto'
];

const diaDelAno = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
const ciudadHoy = ciudades[diaDelAno % ciudades.length];

return {
  ciudad: ciudadHoy,
  query: `barberia en ${ciudadHoy}, Colombia`,
  maxResultadosPorBusqueda: 25
};

const items = $input.all();
const ciudad = $('Elegir Ciudad del Día').first().json.ciudad;
const prospectosAptos = [];
const telefonosProcesados = new Set();

for (const item of items) {
  const data = item.json;
  const rawPhone = data.phone || data.phoneNumber || '';
  let cleanPhone = rawPhone.replace(/[^0-9]/g, '');

  // Normalizar número de Colombia
  if (cleanPhone.length === 10 && cleanPhone.startsWith('3')) {
    cleanPhone = `57${cleanPhone}`;
  } else if (cleanPhone.startsWith('57') && cleanPhone.length === 12 && cleanPhone.slice(2).startsWith('3')) {
    // Ya tiene prefijo 57 y es móvil
  } else {
    // Es fijo o no es un móvil válido de Colombia, se descarta
    continue;
  }

  // Descartar duplicados dentro de la misma lista de resultados
  if (telefonosProcesados.has(cleanPhone)) continue;
  telefonosProcesados.add(cleanPhone);

  // Filtrar que NO tenga página web propia
  const web = (data.website || '').toLowerCase().trim();
  const esSinWebPropia = !web || web === '' || web.includes('facebook.com') || web.includes('instagram.com') || web.includes('business.site') || web.includes('tiktok.com');

  if (esSinWebPropia) {
    prospectosAptos.push({
      barberiaNombre: data.title || data.name || 'Barbería',
      telefono: cleanPhone,
      ciudad: ciudad,
      rating: data.totalScore || 0
    });
  }
}

// Enviamos un máximo de 15 a 20 prospectos al día para máxima seguridad del número
return prospectosAptos.slice(0, 20);

